<script setup lang="ts">
import type { MatterDetailDto } from '~/types/api'
import { errorMessage, todayLocal, statusLabel } from '~/utils/format'
import { matterActions, matterOutcomes, matterSourceLabel, matterStatusLabel, matterOutcomeLabel, matterActionLabel } from '~/utils/matters'
const route = useRoute(), id = computed(() => String(route.params.id)), { bootstrap, load: loadBootstrap } = useAppData()
const detail = ref<MatterDetailDto | null>(null), loading = ref(true), error = ref(''), actionError = ref(''), actionOpen = ref(false), saving = ref(false), deleteOpen = ref(false)
const action = reactive({ kind: 'note', date: todayLocal(), handler: '', notes: '', outcome: '' })
useHead({ title: () => detail.value?.matter.title ?? '事项详情' })
async function load() { loading.value = true; error.value = ''; try { detail.value = await $fetch<MatterDetailDto>(`/api/matters/${id.value}`); await loadBootstrap() } catch (cause) { error.value = errorMessage(cause) } finally { loading.value = false } }
watch(id, load, { immediate: true })
function begin(kind: string) { Object.assign(action, { kind, date: todayLocal(), handler: detail.value?.matter.handler || bootstrap.value?.settings.defaultInspector || '', notes: '', outcome: '' }); actionError.value = ''; actionOpen.value = true }
async function saveAction() { if (saving.value) return; if (!action.notes.trim() || !action.handler.trim() || (action.kind === 'close' && !action.outcome)) { actionError.value = '请填写经办人、办理内容和办结结论'; return } saving.value = true; actionError.value = ''; try { detail.value = await $fetch<MatterDetailDto>(`/api/matters/${id.value}/actions`, { method: 'POST', body: action, retry: 0 }); actionOpen.value = false } catch (cause) { actionError.value = errorMessage(cause) } finally { saving.value = false } }
async function remove() { if (saving.value) return; saving.value = true; actionError.value = ''; try { await $fetch(`/api/matters/${id.value}`, { method: 'DELETE', query: { confirm: true }, retry: 0 }); await navigateTo('/matters') } catch (cause) { actionError.value = errorMessage(cause) } finally { saving.value = false } }
const menu = computed(() => [[...(detail.value?.matter.status !== 'closed' ? [{ label: '编辑事项', to: `/matters/new?edit=${id.value}` }] : []), { label: '删除事项', color: 'error' as const, onSelect: () => { actionError.value = ''; deleteOpen.value = true } }]])
</script>
<template><div class="page-stack"><PageHeader title="事项详情" back="/matters"><template #actions><UDropdownMenu :items="menu"><UButton icon="i-lucide-ellipsis" color="neutral" variant="ghost" aria-label="事项操作" /></UDropdownMenu></template></PageHeader>
<PageState :loading="loading" :error="error" @retry="load"><template v-if="detail">
<section class="panel"><div class="panel-body space-y-3"><div class="flex items-start justify-between gap-3"><h2 class="text-base font-semibold break-words">{{ detail.matter.title }}</h2><StatusBadge :tone="detail.matter.status === 'closed' ? 'success' : detail.matter.overdue ? 'danger' : 'warning'">{{ matterStatusLabel(detail.matter.status) }}</StatusBadge></div><dl class="detail-grid"><div><dt>来源</dt><dd>{{ matterSourceLabel(detail.matter.source) }}</dd></div><div><dt>接收日期</dt><dd>{{ detail.matter.receivedDate }}</dd></div><div><dt>办理期限</dt><dd :class="detail.matter.overdue ? 'text-error' : ''">{{ detail.matter.deadline || '未设置' }}</dd></div><div><dt>经办人</dt><dd><NameTags :value="detail.matter.handler" /></dd></div><div v-if="detail.matter.pointId" class="detail-wide"><dt>关联点位</dt><dd><NuxtLink :to="`/points/${detail.matter.pointId}`" class="text-primary">{{ detail.matter.pointName }}</NuxtLink></dd></div><div v-if="detail.matter.location" class="detail-wide"><dt>涉及地点</dt><dd>{{ detail.matter.location }}</dd></div><div v-if="detail.matter.referenceNumber"><dt>交办编号</dt><dd>{{ detail.matter.referenceNumber }}</dd></div><div v-if="detail.matter.contact || detail.matter.phone"><dt>联系人及方式</dt><dd>{{ detail.matter.contact }} {{ detail.matter.phone }}</dd></div></dl><p class="whitespace-pre-wrap">{{ detail.matter.content }}</p><div v-if="detail.matter.status === 'closed'" class="rounded border border-[var(--border)] p-3"><p class="font-medium">{{ matterOutcomeLabel(detail.matter.outcome) }} · {{ detail.matter.closedDate }}</p><p class="whitespace-pre-wrap">{{ detail.matter.conclusion }}</p></div>
<div class="flex flex-wrap gap-2"><template v-if="detail.matter.status !== 'closed'"><UButton label="添加办理记录" @click="begin('note')" /><UButton label="办结事项" color="neutral" variant="outline" @click="begin('close')" /></template><UButton v-else label="重新办理" @click="begin('reopen')" /></div></div></section>
<RecordRelations kind="matter" :id="id" :tags="detail.matter.tags" @changed="load" />
<section class="panel"><div class="panel-head"><h2 class="section-title">相关工作</h2></div><div class="panel-body space-y-3"><p class="text-sm text-muted">{{ detail.matter.inspectionCount }} 次排查 · {{ detail.matter.issueCount }} 项问题（{{ detail.matter.openIssueCount }} 项未闭环）· {{ detail.matter.activityCount }} 次活动</p><div class="flex flex-wrap gap-2"><UButton :to="{ path: '/inspections/new', query: { matterId: id, pointId: detail.matter.pointId || undefined } }" label="新增排查" color="neutral" variant="outline" /><UButton :to="{ path: '/activities/new', query: { matterId: id } }" label="新增活动" color="neutral" variant="outline" /><MatterAssociate :matter-id="id" @changed="load" /></div>
<div v-if="detail.inspections.length"><h3 class="text-sm font-medium">排查</h3><NuxtLink v-for="record in detail.inspections" :key="record.id" :to="`/inspections/${record.id}`" class="list-row"><span>{{ record.pointName }} · {{ record.date }}</span></NuxtLink></div>
<div v-if="detail.issues.length"><h3 class="text-sm font-medium">整改问题</h3><NuxtLink v-for="issue in detail.issues" :key="issue.id" :to="{ path: `/inspections/${issue.inspectionId}`, query: { issue: issue.id } }" class="list-row"><span class="row-body">{{ issue.description }}</span><StatusBadge :tone="issue.status === 'closed' ? 'success' : 'warning'">{{ statusLabel(issue.status) }}</StatusBadge></NuxtLink></div>
<div v-if="detail.activities.length"><h3 class="text-sm font-medium">活动</h3><NuxtLink v-for="activity in detail.activities" :key="activity.id" :to="`/activities/${activity.id}`" class="list-row">{{ activity.name }} · {{ activity.date }}</NuxtLink></div></div></section>
<section class="panel"><div class="panel-head"><h2 class="section-title">办理过程</h2></div><div class="panel-body"><ol v-if="detail.actions.length" class="action-timeline"><li v-for="item in detail.actions" :key="item.id" class="pb-4"><p class="text-sm font-medium">{{ matterActionLabel(item.kind) }}<span v-if="item.outcome"> · {{ matterOutcomeLabel(item.outcome) }}</span></p><p class="text-xs text-muted">{{ item.date }} · {{ item.handler }}</p><p class="whitespace-pre-wrap">{{ item.notes }}</p></li></ol><EmptyState v-else title="尚无办理记录" /></div></section>
</template></PageState>
<UModal v-model:open="actionOpen" :title="action.kind === 'close' ? '办结事项' : action.kind === 'reopen' ? '重新办理' : '添加办理记录'" :dismissible="!saving" :close="!saving"><template #body><div class="space-y-3"><UAlert role="alert" v-if="actionError" :description="actionError" color="error" /><UFormField v-if="!['close', 'reopen'].includes(action.kind)" label="记录类型"><USelect v-model="action.kind" :items="matterActions" class="w-full" :disabled="saving" data-testid="matter-action-kind" /></UFormField><UFormField v-if="action.kind === 'close'" label="办结结论" required><USelect v-model="action.outcome" :items="matterOutcomes.map(item => ({ ...item, disabled: item.value === 'resolved' && !!detail?.matter.openIssueCount }))" placeholder="请选择" class="w-full" :disabled="saving" /><p v-if="detail?.matter.openIssueCount" class="text-xs text-warning">仍有 {{ detail.matter.openIssueCount }} 项问题未闭环</p></UFormField><UFormField label="办理日期" required><UInput v-model="action.date" type="date" :min="detail?.matter.receivedDate" :max="todayLocal()" class="w-full" :disabled="saving" data-testid="matter-action-date" /></UFormField><UFormField label="经办人" required><NameTagsInput v-model="action.handler" :disabled="saving" :maxlength="200" /></UFormField><UFormField label="办理内容" required><UTextarea v-model="action.notes" :rows="5" :maxlength="12000" class="w-full" :disabled="saving" data-testid="matter-action-notes" /></UFormField></div></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="saving" @click="actionOpen = false" /><UButton label="保存" :loading="saving" data-testid="matter-action-save" @click="saveAction" /></template></UModal>
<UModal v-model:open="deleteOpen" title="删除事项？" description="事项内容和办理过程将删除，已有相关工作记录时不能删除" :dismissible="!saving" :close="!saving"><template #body><UAlert role="alert" v-if="actionError" :description="actionError" color="error" /></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="saving" @click="deleteOpen = false" /><UButton label="删除" color="error" :loading="saving" @click="remove" /></template></UModal>
</div></template>
